const salesStaffListOrders = `-- name: SalesStaffListOrders :many
select o.id, o.order_number, o.channel, o.customer_user_id, o.business_id, o.quote_id, o.pos_shift_id, o.status, o.subtotal_kobo, o.delivery_fee_kobo, o.discount_kobo, o.vat_kobo, o.total_kobo, o.currency, o.ship_to, o.contact_phone, o.price_hash, o.payment_due_at, o.attributed_notification_id, o.placed_at, o.cancelled_at, o.created_at, o.updated_at, o.review_hold_at, o.review_case_id, u.first_name, u.last_name from sales.orders o left join identity.users u on u.id = o.customer_user_id
where ($2::text is null or o.status = $2)
  and ($3::text is null or o.order_number ilike '%' || $3 || '%' or (u.first_name || ' ' || u.last_name) ilike '%' || $3 || '%')
  and ($4::timestamptz is null or o.placed_at < $4)
order by o.placed_at desc limit $1
`

type SalesStaffListOrdersParams struct {
	Limit  int32      `json:"limit"`
	Status *string    `json:"status"`
	Q      *string    `json:"q"`
	Before *time.Time `json:"before"`
}

type SalesStaffListOrdersRow struct {
	ID                       uuid.UUID       `json:"id"`
	OrderNumber              string          `json:"orderNumber"`
	Channel                  string          `json:"channel"`
	CustomerUserID           *uuid.UUID      `json:"customerUserId"`
	BusinessID               *uuid.UUID      `json:"businessId"`
	QuoteID                  *uuid.UUID      `json:"quoteId"`
	PosShiftID               *uuid.UUID      `json:"posShiftId"`
	Status                   string          `json:"status"`
	SubtotalKobo             int64           `json:"subtotalKobo"`
	DeliveryFeeKobo          int64           `json:"deliveryFeeKobo"`
	DiscountKobo             int64           `json:"discountKobo"`
	VatKobo                  int64           `json:"vatKobo"`
	TotalKobo                int64           `json:"totalKobo"`
	Currency                 string          `json:"currency"`
	ShipTo                   json.RawMessage `json:"shipTo"`
	ContactPhone             *string         `json:"contactPhone"`
	PriceHash                *string         `json:"priceHash"`
	PaymentDueAt             *time.Time      `json:"paymentDueAt"`
	AttributedNotificationID *uuid.UUID      `json:"attributedNotificationId"`
	PlacedAt                 time.Time       `json:"placedAt"`
	CancelledAt              *time.Time      `json:"cancelledAt"`
	CreatedAt                time.Time       `json:"createdAt"`
	UpdatedAt                time.Time       `json:"updatedAt"`
	ReviewHoldAt             *time.Time      `json:"reviewHoldAt"`
	ReviewCaseID             *uuid.UUID      `json:"reviewCaseId"`
	FirstName                *string         `json:"firstName"`
	LastName                 *string         `json:"lastName"`
}

func (q *Queries) SalesStaffListOrders(ctx context.Context, arg SalesStaffListOrdersParams) ([]SalesStaffListOrdersRow, error) {
	rows, err := q.db.Query(ctx, salesStaffListOrders,
		arg.Limit,
		arg.Status,
		arg.Q,
		arg.Before,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SalesStaffListOrdersRow{}
	for rows.Next() {
		var i SalesStaffListOrdersRow
		if err := rows.Scan(
			&i.ID,
			&i.OrderNumber,
			&i.Channel,
			&i.CustomerUserID,
			&i.BusinessID,
			&i.QuoteID,
			&i.PosShiftID,
			&i.Status,
			&i.SubtotalKobo,
			&i.DeliveryFeeKobo,
			&i.DiscountKobo,
			&i.VatKobo,
			&i.TotalKobo,
			&i.Currency,
			&i.ShipTo,
			&i.ContactPhone,
			&i.PriceHash,
			&i.PaymentDueAt,
			&i.AttributedNotificationID,
			&i.PlacedAt,
			&i.CancelledAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ReviewHoldAt,
			&i.ReviewCaseID,
			&i.FirstName,
			&i.LastName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

